//! Locale formatting from a built-in CLDR subset (`cldr.rs`, generated by
//! `scripts/cldr.ts`): compact numbers ("1.2K", "1,2 Mio."), currency
//! amounts, dates, times and durations, for the languages og-i18n's plural
//! rules cover (plus zh-Hant). Every function is pure: a date or time is a
//! number of seconds the caller passes in (since 1970-01-01 00:00 UTC, plus
//! an offset), never a clock read, so a formatted string is the same on
//! every host and in a replay.

use crate::locale::{canonical, chinese_script, language};

/// One locale's CLDR data.
pub(crate) struct LocaleData {
    pub tag: &'static str,
    /// The numbering system's ten digits when it is not latn (bn, mr, my,
    /// fa): written for 0 to 9.
    pub digits: Option<&'static str>,
    pub decimal: &'static str,
    pub group: &'static str,
    pub minus: &'static str,
    pub time_separator: &'static str,
    pub hours: &'static [(&'static str, &'static str)],
    pub minutes: &'static [(&'static str, &'static str)],
    /// The primary and secondary group sizes (3, 3; Indian 3, 2).
    pub grouping: (u8, u8),
    /// Digits a whole part needs past the primary group before it groups
    /// (2 in es and pl: 1234 is not grouped there).
    pub min_grouping: u8,
    /// The short compact patterns for 10^3 to 10^14: (zeros, prefix,
    /// suffix); zeros 0 is not compacted at that size.
    pub compact: [(u8, &'static str, &'static str); 12],
    /// The standard currency pattern (`¤#,##0.00`).
    pub currency: &'static str,
    /// Currency symbols that differ from en's.
    pub symbols: &'static [(&'static str, &'static str)],
    pub months: [&'static str; 12],
    pub months_short: [&'static str; 12],
    pub months_standalone: [&'static str; 12],
    pub months_standalone_short: [&'static str; 12],
    pub month_year: &'static str,
    /// Sunday first.
    pub days: [&'static str; 7],
    pub days_short: [&'static str; 7],
    pub am: &'static str,
    pub pm: &'static str,
    /// The full, long, medium and short date patterns.
    pub date: [&'static str; 4],
    /// The medium and short time patterns.
    pub time: [&'static str; 2],
}

/// A currency the subset knows: its en symbol and fraction digits.
pub(crate) struct Currency {
    pub code: &'static str,
    pub symbol: &'static str,
    pub digits: u8,
}

/// How much of a date to write (CLDR's styles): `Full` "Monday, November
/// 2, 2026", `Long` "November 2, 2026", `Medium` "Nov 2, 2026", `Short`
/// "11/2/26" (en).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DateStyle {
    Full,
    Long,
    Medium,
    Short,
    MonthYear,
    MonthName,
    Weekday,
    WeekdayShort,
}

impl DateStyle {
    /// `full`, `long`, `medium` or `short`.
    pub fn named(name: &str) -> Option<DateStyle> {
        Some(match name {
            "full" => DateStyle::Full,
            "long" => DateStyle::Long,
            "medium" => DateStyle::Medium,
            "short" => DateStyle::Short,
            "monthYear" => DateStyle::MonthYear,
            "monthName" => DateStyle::MonthName,
            "weekday" => DateStyle::Weekday,
            "weekdayShort" => DateStyle::WeekdayShort,
            _ => return None,
        })
    }
}

/// How much of a time to write: `Medium` with seconds, `Short` without.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TimeStyle {
    Medium,
    Short,
}

impl TimeStyle {
    /// `medium` or `short`.
    pub fn named(name: &str) -> Option<TimeStyle> {
        Some(match name {
            "medium" => TimeStyle::Medium,
            "short" => TimeStyle::Short,
            _ => return None,
        })
    }
}

/// The CLDR tags the subset carries, sorted.
pub fn format_locales() -> Vec<&'static str> {
    crate::cldr::LOCALES.iter().map(|l| l.tag).collect()
}

/// The data for a BCP 47 tag: its language's (Chinese by script: zh-TW and
/// zh-Hant take zh-Hant), else en's.
fn data(locale: &str) -> &'static LocaleData {
    let lang = language(locale);
    let tag = match lang.as_str() {
        "zh" if chinese_script(&canonical(locale)) == "Hant" => "zh-Hant",
        "no" | "nn" => "nb",
        "iw" => "he",
        other => other,
    };
    let all = crate::cldr::LOCALES;
    all.binary_search_by(|l| l.tag.cmp(tag))
        .or_else(|_| all.binary_search_by(|l| l.tag.cmp("en")))
        .map(|i| &all[i])
        .expect("the subset has en")
}

/// ASCII digits written in the locale's numbering system.
fn native(text: String, d: &LocaleData) -> String {
    let Some(digits) = d.digits else {
        return text;
    };
    let digits: Vec<char> = digits.chars().collect();
    text.chars()
        .map(|c| match c.to_digit(10) {
            Some(n) if c.is_ascii_digit() => digits[n as usize],
            _ => c,
        })
        .collect()
}

/// `n.abs()` with `fraction` digits (fewer when `trim`: trailing zeros
/// dropped), its whole part grouped as `grouping` says, in ASCII digits
/// with the locale's separators.
fn digits(n: f64, fraction: usize, trim: bool, grouping: (u8, u8), d: &LocaleData) -> String {
    let text = format!("{:.*}", fraction, n.abs());
    let (int, frac) = text.split_once('.').unwrap_or((&text, ""));
    let frac = if trim {
        frac.trim_end_matches('0')
    } else {
        frac
    };
    let (primary, secondary) = (grouping.0 as usize, grouping.1 as usize);
    let mut out = String::new();
    if primary == 0 || int.len() < primary + d.min_grouping as usize {
        out.push_str(int);
    } else {
        // Groups from the right: the primary, then secondary ones.
        let mut cuts = vec![int.len() - primary];
        while *cuts.last().unwrap() > secondary {
            cuts.push(cuts.last().unwrap() - secondary);
        }
        let mut from = 0;
        for &cut in cuts.iter().rev() {
            out.push_str(&int[from..cut]);
            out.push_str(d.group);
            from = cut;
        }
        out.push_str(&int[from..]);
    }
    if !frac.is_empty() {
        out.push_str(d.decimal);
        out.push_str(frac);
    }
    out
}

/// Pseudo locales deliberately expand formatted text for layout testing.
pub fn is_pseudo_locale(locale: &str) -> bool {
    matches!(canonical(locale).as_str(), "pseudo" | "en-XA" | "ar-XB")
}

fn finish(text: String, locale: &str) -> String {
    if !is_pseudo_locale(locale) {
        return text;
    }
    let padding = "~".repeat((text.chars().count() * 2).div_ceil(5));
    let text: String = text
        .chars()
        .map(|c| match c {
            'a' => 'à',
            'e' => 'ë',
            'i' => 'ï',
            'o' => 'ô',
            'u' => 'ü',
            'A' => 'À',
            'E' => 'Ë',
            'I' => 'Ï',
            'O' => 'Ô',
            'U' => 'Ü',
            other => other,
        })
        .collect();
    let text = format!("[{text}{padding}]");
    if canonical(locale) == "ar-XB" {
        format!("\u{2067}{text}\u{2069}")
    } else {
        text
    }
}

/// Decimal digits, grouping and signs from CLDR. With no explicit precision,
/// keep up to three fraction digits; otherwise keep exactly 0..20 digits.
pub fn format_decimal(value: f64, decimals: Option<u8>, grouping: bool, locale: &str) -> String {
    if !value.is_finite() {
        return finish(value.to_string(), locale);
    }
    let d = data(locale);
    let body = digits(
        value,
        decimals.unwrap_or(3).min(20) as usize,
        decimals.is_none(),
        if grouping { d.grouping } else { (0, 0) },
        d,
    );
    let nonzero = body.chars().any(|c| c.is_ascii_digit() && c != '0');
    let sign = if value < 0.0 && nonzero { d.minus } else { "" };
    finish(native(format!("{sign}{body}"), d), locale)
}

/// A number written short: "1.2K", "12K", "1.2M" in en, "1,2 Mio." in de,
/// "1.2万" in ja (CLDR's short compact patterns). Below the first compact
/// size, or where the locale compacts none (de's thousands), the number in
/// full; a compact value under 100 keeps two significant digits, a larger
/// one is whole.
pub fn format_compact(value: f64, locale: &str) -> String {
    format_compact_with_precision(value, None, locale)
}

/// Compact notation with optional fixed fractional digits (0..20).
pub fn format_compact_with_precision(value: f64, decimals: Option<u8>, locale: &str) -> String {
    let d = data(locale);
    if !value.is_finite() {
        return finish(value.to_string(), locale);
    }
    let n = value.abs();
    let round = |x: f64| {
        if let Some(decimals) = decimals {
            let decimals = decimals.min(20);
            let scale = 10f64.powi(decimals as i32);
            let scaled = x * scale;
            (
                if scaled.is_finite() {
                    scaled.round() / scale
                } else {
                    x
                },
                decimals as usize,
            )
        } else if x >= 10.0 {
            (x.round(), 0)
        } else {
            ((x * 10.0).round() / 10.0, 1)
        }
    };
    // The size class: digits of the whole part less one, once rounding
    // has carried (999,999 is 1M, not 1000K).
    let mut e = if n >= 1.0 {
        (n.round().to_string().len() as i32 - 1).min(14)
    } else {
        0
    };
    let mut body = None;
    while e >= 3 {
        let (zeros, prefix, suffix) = d.compact[(e as usize - 3).min(11)];
        if zeros == 0 {
            break;
        }
        let scale = 10f64.powi(e - zeros as i32 + 1);
        let (x, fraction) = round(n / scale);
        if x >= 10f64.powi(zeros as i32) && e < 14 {
            e += 1;
            continue;
        }
        body = Some(format!(
            "{prefix}{}{suffix}",
            digits(x, fraction, decimals.is_none(), (0, 0), d)
        ));
        break;
    }
    let body = body.unwrap_or_else(|| {
        let (x, fraction) = if n >= 1000.0 && decimals.is_none() {
            (n.round(), 0)
        } else {
            round(n)
        };
        digits(x, fraction, decimals.is_none(), d.grouping, d)
    });
    let sign = if value < 0.0 && body.chars().any(|c| c.is_ascii_digit() && c != '0') {
        d.minus
    } else {
        ""
    };
    finish(native(format!("{sign}{body}"), d), locale)
}

/// An amount of a currency (an ISO 4217 code) as the locale writes it:
/// "$1,234.50" in en, "1.234,50 $" in de, "￥1,235" in ja, with the
/// currency's own fraction digits (0 for JPY and KRW). A code the subset
/// does not know is written as itself with two digits.
pub fn format_currency(amount: f64, code: &str, locale: &str) -> String {
    let d = data(locale);
    let code = code.trim().to_ascii_uppercase();
    let known = crate::cldr::CURRENCIES.iter().find(|c| c.code == code);
    let symbol = d
        .symbols
        .iter()
        .find(|(c, _)| *c == code)
        .map(|(_, s)| *s)
        .or(known.map(|c| c.symbol))
        .unwrap_or(&code);
    let fraction = known.map_or(2, |c| c.digits as usize);
    if !amount.is_finite() {
        return amount.to_string();
    }
    // The pattern's number: from its first '#' or '0' to its last '0'.
    let p = d.currency;
    let start = p.find(['#', '0']).unwrap_or(0);
    let end = p.rfind('0').map_or(p.len(), |i| i + 1);
    let number = digits(amount, fraction, false, pattern_grouping(&p[start..end]), d);
    let (before, after) = (&p[..start], &p[end..]);
    let zero = !number.chars().any(|c| c.is_ascii_digit() && c != '0');
    // A minus leads the number, or the symbol right before it.
    let minus = if amount < 0.0 && !zero { d.minus } else { "" };
    let text = if minus.is_empty() {
        format!("{before}{number}{after}")
    } else if before.ends_with('¤') {
        format!("{minus}{before}{number}{after}")
    } else {
        format!("{before}{minus}{number}{after}")
    };
    finish(native(text.replace('¤', symbol), d), locale)
}

/// The primary and secondary group sizes of a number pattern
/// (`#,##,##0.00`: 3, 2).
pub(crate) fn pattern_grouping(p: &str) -> (u8, u8) {
    let int = p.split('.').next().unwrap_or(p);
    let parts: Vec<&str> = int.split(',').collect();
    if parts.len() < 2 {
        return (0, 0);
    }
    let primary = parts[parts.len() - 1].len() as u8;
    let secondary = if parts.len() > 2 {
        parts[parts.len() - 2].len() as u8
    } else {
        primary
    };
    (primary, secondary)
}

/// The civil date and time of `seconds` since 1970-01-01 00:00 UTC moved by
/// `offset_minutes`: (year, month 1-12, day, weekday 0 Sunday, seconds of
/// the day). Whole seconds, rounded down; integer arithmetic only.
fn civil(seconds: f64, offset_minutes: i32) -> (i64, u32, u32, u32, u32) {
    let t = if seconds.is_finite() {
        seconds.floor() as i64
    } else {
        0
    } + offset_minutes as i64 * 60;
    let days = t.div_euclid(86_400);
    let secs = t.rem_euclid(86_400) as u32;
    // Howard Hinnant's days_from_civil inverse.
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let month = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let year = yoe + era * 400 + i64::from(month <= 2);
    let weekday = (days + 4).rem_euclid(7) as u32;
    (year, month, day, weekday, secs)
}

/// Writes a CLDR date or time pattern for `seconds` and `offset_minutes`.
fn pattern(p: &str, seconds: f64, offset_minutes: i32, d: &LocaleData) -> String {
    let (year, month, day, weekday, secs) = civil(seconds, offset_minutes);
    let (hour, minute, second) = (secs / 3600, secs / 60 % 60, secs % 60);
    let pad = |n: u32, width: usize| format!("{n:0width$}");
    let chars: Vec<char> = p.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\'' {
            // A quoted run ('' is a quote).
            if chars.get(i + 1) == Some(&'\'') {
                out.push('\'');
                i += 2;
                continue;
            }
            i += 1;
            while i < chars.len() {
                if chars[i] == '\'' {
                    if chars.get(i + 1) == Some(&'\'') {
                        out.push('\'');
                        i += 2;
                        continue;
                    }
                    i += 1;
                    break;
                }
                out.push(chars[i]);
                i += 1;
            }
            continue;
        }
        if !c.is_ascii_alphabetic() {
            out.push(c);
            i += 1;
            continue;
        }
        let mut n = 1;
        while chars.get(i + n) == Some(&c) {
            n += 1;
        }
        i += n;
        let h12 = if hour % 12 == 0 { 12 } else { hour % 12 };
        match c {
            'y' | 'Y' | 'u' => {
                if n == 2 {
                    out.push_str(&pad(year.rem_euclid(100) as u32, 2));
                } else {
                    out.push_str(&year.to_string());
                }
            }
            'M' => match n {
                1 | 2 => out.push_str(&pad(month, n)),
                3 => out.push_str(d.months_short[month as usize - 1]),
                _ => out.push_str(d.months[month as usize - 1]),
            },
            'L' => match n {
                1 | 2 => out.push_str(&pad(month, n)),
                3 => out.push_str(d.months_standalone_short[month as usize - 1]),
                _ => out.push_str(d.months_standalone[month as usize - 1]),
            },
            'd' => out.push_str(&pad(day, n)),
            'E' | 'c' | 'e' => {
                if n >= 4 {
                    out.push_str(d.days[weekday as usize]);
                } else {
                    out.push_str(d.days_short[weekday as usize]);
                }
            }
            'a' | 'b' | 'B' => out.push_str(if hour < 12 { d.am } else { d.pm }),
            'h' => out.push_str(&pad(h12, n)),
            'K' => out.push_str(&pad(hour % 12, n)),
            'H' => out.push_str(&pad(hour, n)),
            'k' => out.push_str(&pad(if hour == 0 { 24 } else { hour }, n)),
            'm' => out.push_str(&pad(minute, n)),
            's' => out.push_str(&pad(second, n)),
            // Eras, time zones and the rest: not in the styles used.
            _ => {}
        }
    }
    native(out.trim().to_string(), d)
}

/// A date as the locale writes it in `style` ("Nov 2, 2026", "2.11.26"):
/// `seconds` since 1970-01-01 00:00 UTC, shown `offset_minutes` ahead of
/// UTC (a player's time zone, which the game passes in).
pub fn format_date(seconds: f64, offset_minutes: i32, style: DateStyle, locale: &str) -> String {
    let d = data(locale);
    let p = match style {
        DateStyle::Full => d.date[0],
        DateStyle::Long => d.date[1],
        DateStyle::Medium => d.date[2],
        DateStyle::Short => d.date[3],
        DateStyle::MonthYear => d.month_year,
        DateStyle::MonthName => "LLLL",
        DateStyle::Weekday => "EEEE",
        DateStyle::WeekdayShort => "EEE",
    };
    finish(pattern(p, seconds, offset_minutes, d), locale)
}

/// A time of day as the locale writes it ("3:05 PM", "15:05"), as
/// [`format_date`] takes its moment.
pub fn format_time(seconds: f64, offset_minutes: i32, style: TimeStyle, locale: &str) -> String {
    let d = data(locale);
    let p = d.time[match style {
        TimeStyle::Medium => 0,
        TimeStyle::Short => 1,
    }];
    finish(pattern(p, seconds, offset_minutes, d), locale)
}

/// A length of time on a clock face: "1:02:03" from an hour, else "2:03",
/// whole seconds rounded down, in the locale's digits and time separator.
pub fn format_duration(seconds: f64, locale: &str) -> String {
    let d = data(locale);
    let s = if seconds.is_finite() {
        seconds.abs().floor() as u64
    } else {
        0
    };
    let sep = d.time_separator;
    let (h, m, sec) = (s / 3600, s / 60 % 60, s % 60);
    let body = if h > 0 {
        format!("{h}{sep}{m:02}{sep}{sec:02}")
    } else {
        format!("{m}{sep}{sec:02}")
    };
    let sign = if seconds < 0.0 && s > 0 { d.minus } else { "" };
    finish(native(format!("{sign}{body}"), d), locale)
}

/// A cooldown label: rounded up to its largest whole unit, using CLDR's
/// narrow hour/minute patterns. Under a minute it is a whole second count.
pub fn format_duration_short(seconds: f64, locale: &str) -> String {
    let d = data(locale);
    let magnitude = seconds.abs();
    let (value, patterns) = if magnitude >= 3600.0 {
        ((magnitude / 3600.0).ceil(), d.hours)
    } else if magnitude >= 60.0 {
        ((magnitude / 60.0).ceil(), d.minutes)
    } else {
        return format_decimal(seconds.signum() * magnitude.ceil(), Some(0), false, locale);
    };
    let category = crate::plural_category(locale, value).keyword();
    let pattern = patterns
        .iter()
        .find(|(k, _)| *k == category)
        .or_else(|| patterns.iter().find(|(k, _)| *k == "other"))
        .expect("CLDR other pattern")
        .1;
    let sign = if seconds < 0.0 { d.minus } else { "" };
    let number = format!("{sign}{}", digits(value, 0, false, (0, 0), d));
    finish(native(pattern.replace("{0}", &number), d), locale)
}

#[cfg(test)]
mod tests {
    use super::*;

    // Expected strings are CLDR 49's patterns written out by hand (and ICU's
    // output for the same values); epoch seconds are from Python's datetime.

    #[test]
    fn decimal_and_calendar_formats_share_locale_data() {
        assert_eq!(
            format_decimal(1234567.5, Some(2), true, "hi-IN"),
            "12,34,567.50"
        );
        assert_eq!(format_decimal(1234.5, None, true, "bn"), "১,২৩৪.৫");
        assert_eq!(format_decimal(1234.5, Some(2), false, "de-DE"), "1234,50");
        assert_eq!(format_decimal(-0.001, Some(2), true, "en"), "0.00");
        assert_eq!(
            format_decimal(-1234.5, None, true, "ar"),
            "\u{200e}-1,234.5"
        );
        assert_eq!(format_decimal(1234.0, None, true, "es"), "1234");
        assert_eq!(format_decimal(12345.0, None, true, "es"), "12.345");
        let args = [("n".into(), crate::Arg::Num(1234567.5))].into();
        assert_eq!(
            crate::Message::parse("{n, number}")
                .unwrap()
                .format("hi-IN", &args),
            "12,34,567.5"
        );
        let t = 1_793_631_909.0;
        assert_eq!(format_date(t, 0, DateStyle::MonthYear, "ja"), "2026年11月");
        assert_eq!(format_date(t, 0, DateStyle::MonthName, "ru"), "ноябрь");
        assert_eq!(format_date(t, 0, DateStyle::WeekdayShort, "de"), "Mo.");
        assert_eq!(
            format_compact_with_precision(12345.0, Some(2), "ja"),
            "1.23万"
        );
        assert_eq!(format_compact(1e15, "en"), "1000T");
        assert_eq!(format_duration_short(3601.0, "en"), "2h");
        assert_eq!(format_duration_short(125.0, "ar"), "3 د");
    }

    #[test]
    fn pseudo_formats_expand_numbers_and_temporal_text() {
        assert_eq!(format_decimal(1234.5, None, true, "en-XA"), "[1,234.5~~~]");
        assert_eq!(format_compact(1200.0, "pseudo"), "[1.2K~~]");
        assert_eq!(format_duration(125.0, "en-XA"), "[2:05~~]");
        assert_eq!(
            format_date(0.0, 0, DateStyle::Medium, "en-XA"),
            "[Jàn 1, 1970~~~~~]"
        );
        assert_eq!(
            format_time(0.0, 0, TimeStyle::Medium, "en-XA"),
            "[12:00:00\u{202f}ÀM~~~~~]"
        );
        assert_eq!(
            format_decimal(12.0, None, true, "ar-XB"),
            "\u{2067}[12~]\u{2069}"
        );
    }

    #[test]
    fn compact_follows_each_locales_patterns() {
        assert_eq!(format_compact(999.0, "en"), "999");
        assert_eq!(format_compact(1234.0, "en"), "1.2K");
        assert_eq!(format_compact(12_345.0, "en"), "12K");
        assert_eq!(format_compact(123_456.0, "en"), "123K");
        // Rounding carries into the next size: not \"1000K\".
        assert_eq!(format_compact(999_999.0, "en-US"), "1M");
        assert_eq!(format_compact(-1500.0, "en"), "-1.5K");
        assert_eq!(format_compact(2.5e12, "en"), "2.5T");
        // de compacts no thousands, then \"Mio.\" after a no-break space.
        assert_eq!(format_compact(12_345.0, "de"), "12.345");
        assert_eq!(format_compact(1_234_567.0, "de-AT"), "1,2\u{a0}Mio.");
        // ja and zh-Hant count in 万/萬 (10^4), not thousands.
        assert_eq!(format_compact(1234.0, "ja"), "1,234");
        assert_eq!(format_compact(12_345.0, "ja"), "1.2万");
        assert_eq!(format_compact(123_456_789.0, "zh-TW"), "1.2億");
        assert_eq!(format_compact(123_456_789.0, "zh-CN"), "1.2亿");
        // hi: lakh at 10^5; bn writes Bengali digits.
        assert_eq!(format_compact(123_456.0, "hi"), "1.2\u{a0}लाख");
        assert_eq!(format_compact(1234.0, "bn"), "১.২\u{a0}হা");
        // An unknown locale is en.
        assert_eq!(format_compact(1234.0, "xx"), "1.2K");
    }

    #[test]
    fn currency_uses_the_pattern_symbol_and_digits() {
        assert_eq!(format_currency(1234.5, "USD", "en"), "$1,234.50");
        assert_eq!(format_currency(-5.0, "usd", "en"), "-$5.00");
        assert_eq!(format_currency(1234.5, "EUR", "de"), "1.234,50\u{a0}€");
        // JPY has no fraction; ja writes its own yen sign.
        assert_eq!(format_currency(1234.6, "JPY", "ja"), "￥1,235");
        assert_eq!(format_currency(1234.6, "JPY", "en"), "¥1,235");
        // Indian grouping from the pattern (#,##,##0.00).
        assert_eq!(format_currency(1_234_567.5, "INR", "hi"), "₹12,34,567.50");
        // es groups only from five digits.
        assert_eq!(format_currency(1234.5, "EUR", "es"), "1234,50\u{a0}€");
        assert_eq!(format_currency(12_345.5, "EUR", "es"), "12.345,50\u{a0}€");
        assert_eq!(
            format_currency(1234.5, "EUR", "fr"),
            "1\u{202f}234,50\u{a0}€"
        );
        // A code the subset lacks is written as itself.
        assert_eq!(format_currency(3.0, "XTS", "en"), "XTS3.00");
    }

    #[test]
    fn dates_and_times_are_civil_utc_plus_the_offset() {
        // 2026-11-02 15:05:09 UTC, a Monday.
        let t = 1_793_631_909.0;
        assert_eq!(
            format_date(t, 0, DateStyle::Full, "en"),
            "Monday, November 2, 2026"
        );
        assert_eq!(format_date(t, 0, DateStyle::Medium, "en"), "Nov 2, 2026");
        assert_eq!(format_date(t, 0, DateStyle::Short, "en"), "11/2/26");
        assert_eq!(format_date(t, 0, DateStyle::Short, "de"), "02.11.26");
        assert_eq!(
            format_date(t, 0, DateStyle::Full, "de"),
            "Montag, 2. November 2026"
        );
        assert_eq!(
            format_date(t, 0, DateStyle::Long, "es"),
            "2 de noviembre de 2026"
        );
        assert_eq!(format_date(t, 0, DateStyle::Long, "ja"), "2026年11月2日");
        assert_eq!(format_time(t, 0, TimeStyle::Short, "en"), "3:05\u{202f}PM");
        assert_eq!(format_time(t, 0, TimeStyle::Medium, "de"), "15:05:09");
        assert_eq!(format_time(t, 0, TimeStyle::Short, "zh-TW"), "下午3:05");
        // Nine hours ahead is past midnight: the next day.
        assert_eq!(format_date(t, 9 * 60, DateStyle::Short, "en"), "11/3/26");
        assert_eq!(
            format_time(t, 9 * 60, TimeStyle::Short, "en"),
            "12:05\u{202f}AM"
        );
        // A leap day, the epoch, before it, and before 1901.
        assert_eq!(
            format_date(1_709_164_800.0, 0, DateStyle::Medium, "en"),
            "Feb 29, 2024"
        );
        assert_eq!(format_date(0.0, 0, DateStyle::Medium, "en"), "Jan 1, 1970");
        assert_eq!(format_time(-1.0, 0, TimeStyle::Medium, "de"), "23:59:59");
        assert_eq!(format_date(-1.0, 0, DateStyle::Short, "en"), "12/31/69");
        assert_eq!(
            format_date(-2_203_891_200.0, 0, DateStyle::Full, "en"),
            "Thursday, March 1, 1900"
        );
    }

    #[test]
    fn durations_are_clock_faces() {
        assert_eq!(format_duration(3723.9, "en"), "1:02:03");
        assert_eq!(format_duration(125.0, "de"), "2:05");
        assert_eq!(format_duration(-125.0, "en"), "-2:05");
        assert_eq!(format_duration(0.4, "en"), "0:00");
        assert_eq!(format_duration(125.0, "bn"), "২:০৫");
    }

    #[test]
    fn the_subset_covers_every_plural_language() {
        let tags = format_locales();
        assert!(tags.windows(2).all(|w| w[0] < w[1]), "sorted for lookup");
        for lang in [
            "en", "de", "fr", "ja", "zh", "zh-Hant", "ko", "ar", "hi", "ru", "pt",
        ] {
            assert!(tags.contains(&lang), "{lang}");
        }
    }
}
